create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','member');
create type public.deadline_status as enum ('active','completed','dismissed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table public.households (id uuid primary key default gen_random_uuid(), name text not null, owner_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.household_members (household_id uuid references public.households(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role public.member_role not null default 'member', created_at timestamptz not null default now(), primary key(household_id,user_id));
create table public.categories (id uuid primary key default gen_random_uuid(), name text unique not null, icon text);
insert into public.categories(name) values ('Electronics'),('Appliances'),('Furniture'),('Clothing'),('Tools'),('Household'),('Other') on conflict do nothing;
create table public.purchases (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, household_id uuid references public.households(id) on delete set null, merchant text, product_name text not null, category text, purchase_date date, purchase_price numeric(12,2), currency char(3) not null default 'USD', serial_number text, model_number text, sku text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.purchases(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, kind text not null default 'other' check (kind in ('receipt','invoice','warranty','manual','other')), name text not null, storage_path text not null, mime_type text not null, size_bytes bigint not null check (size_bytes between 1 and 20971520), created_at timestamptz not null default now());
create table public.warranties (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.purchases(id) on delete cascade, provider text, type text, start_date date, end_date date, terms_summary text, source_document_id uuid references public.documents(id) on delete set null, created_at timestamptz not null default now());
create table public.return_windows (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.purchases(id) on delete cascade, merchant text, start_date date, end_date date, policy_summary text, source_document_id uuid references public.documents(id) on delete set null);
create table public.deadlines (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.purchases(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, type text not null, title text not null, description text, deadline_date date not null, status public.deadline_status not null default 'active', reminder_30_days boolean not null default true, reminder_7_days boolean not null default true, reminder_1_day boolean not null default true, created_at timestamptz not null default now());
create table public.product_photos (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.purchases(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, storage_path text not null, created_at timestamptz not null default now());
create table public.service_records (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.purchases(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, service_date date, provider text, description text not null, cost numeric(12,2), created_at timestamptz not null default now());
create table public.ai_conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, purchase_id uuid references public.purchases(id) on delete cascade, created_at timestamptz not null default now());
create table public.ai_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.ai_conversations(id) on delete cascade, role text not null check (role in ('user','assistant')), content text not null, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, purchase_id uuid references public.purchases(id) on delete cascade, deadline_id uuid references public.deadlines(id) on delete cascade, title text not null, body text not null, read_at timestamptz, scheduled_for timestamptz, created_at timestamptz not null default now());
create table public.subscriptions (user_id uuid primary key references auth.users(id) on delete cascade, plan text not null default 'free' check (plan in ('free','pro')), provider_customer_id text, provider_subscription_id text, status text not null default 'active', updated_at timestamptz not null default now());
-- Helpers are security-definer to avoid recursive RLS through household_members.
create function public.is_household_member(hid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from household_members where household_id=hid and user_id=auth.uid()) $$;
create function public.can_access_purchase(pid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from purchases p where p.id=pid and (p.user_id=auth.uid() or (p.household_id is not null and is_household_member(p.household_id)))) $$;
-- All owner data is private by default. A shared purchase requires explicit household_id membership.
do $$ declare t text; begin foreach t in array array['profiles','households','household_members','purchases','documents','warranties','return_windows','deadlines','product_photos','service_records','ai_conversations','ai_messages','notifications','subscriptions'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "profiles own" on profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "household members view household" on households for select using(is_household_member(id)); create policy "household owner manages" on households for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "members see household membership" on household_members for select using(is_household_member(household_id)); create policy "owner manages members" on household_members for all using(exists(select 1 from households h where h.id=household_id and h.owner_id=auth.uid())) with check(exists(select 1 from households h where h.id=household_id and h.owner_id=auth.uid()));
create policy "purchase access" on purchases for select using(user_id=auth.uid() or (household_id is not null and is_household_member(household_id))); create policy "purchase owner insert" on purchases for insert with check(user_id=auth.uid() and (household_id is null or is_household_member(household_id))); create policy "purchase owner update" on purchases for update using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "purchase owner delete" on purchases for delete using(user_id=auth.uid());
create policy "documents access" on documents for select using(user_id=auth.uid() or can_access_purchase(purchase_id)); create policy "documents owner insert" on documents for insert with check(user_id=auth.uid() and can_access_purchase(purchase_id)); create policy "documents owner update" on documents for update using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "documents owner delete" on documents for delete using(user_id=auth.uid());
create policy "warranty purchase access" on warranties for select using(can_access_purchase(purchase_id)); create policy "warranty owner write" on warranties for all using(exists(select 1 from purchases p where p.id=purchase_id and p.user_id=auth.uid())) with check(exists(select 1 from purchases p where p.id=purchase_id and p.user_id=auth.uid()));
create policy "return purchase access" on return_windows for select using(can_access_purchase(purchase_id)); create policy "return owner write" on return_windows for all using(exists(select 1 from purchases p where p.id=purchase_id and p.user_id=auth.uid())) with check(exists(select 1 from purchases p where p.id=purchase_id and p.user_id=auth.uid()));
create policy "deadlines own" on deadlines for all using(user_id=auth.uid()) with check(user_id=auth.uid() and can_access_purchase(purchase_id));
create policy "photos own" on product_photos for all using(user_id=auth.uid() and can_access_purchase(purchase_id)) with check(user_id=auth.uid() and can_access_purchase(purchase_id));
create policy "service own" on service_records for all using(user_id=auth.uid() and can_access_purchase(purchase_id)) with check(user_id=auth.uid() and can_access_purchase(purchase_id));
create policy "conversation own" on ai_conversations for all using(user_id=auth.uid()) with check(user_id=auth.uid() and (purchase_id is null or can_access_purchase(purchase_id)));
create policy "messages own conversation" on ai_messages for all using(exists(select 1 from ai_conversations c where c.id=conversation_id and c.user_id=auth.uid())) with check(exists(select 1 from ai_conversations c where c.id=conversation_id and c.user_id=auth.uid()));
create policy "notifications own" on notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "subscription own" on subscriptions for select using(user_id=auth.uid());
-- Private storage buckets; clients should use signed URLs, never public URLs.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('purchase-documents','purchase-documents',false,20971520,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy "private document files read" on storage.objects for select using(bucket_id='purchase-documents' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "private document files upload" on storage.objects for insert with check(bucket_id='purchase-documents' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "private document files delete" on storage.objects for delete using(bucket_id='purchase-documents' and (storage.foldername(name))[1]=auth.uid()::text);
